import{z as o,x as s,o as A,c as d,q as r,j as n,D as t,d as E,s as B,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"自动微分的实现","description":"","frontmatter":{"title":"自动微分的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sc-autodiff-implementation.md","filePath":"cs/sc-autodiff-implementation.md","lastUpdated":1791063341000}'),p={name:"cs/sc-autodiff-implementation.md"};function m(D,a,c,f,u,h){const i=s("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="自动微分的实现" tabindex="-1">自动微分的实现 <a class="header-anchor" href="#自动微分的实现" aria-label="Permalink to &quot;自动微分的实现&quot;">​</a></h1><div class="epigraph"><p>链式法则只有一个，实现却要回答程序问题：导数放在哪、何时算、内存换时间换到哪一档。</p><footer>—— 据 Griewank and Walther, Evaluating Derivatives, SIAM, 2008；Baydin et al., JMLR, 2018 整理</footer></div><p><a href="/cs/sc-sparse-computing">上一课</a>把线性代数按非零结构组织；本课把导数按计算结构组织。两种模式的复杂度账——正向算 \\(Jv\\)、反向算 \\(u^\\top J\\)——大模型栏的<a href="/llm/autograd-two-modes">自动微分的正向与反向模式</a>已经算过，计算图的视角在<a href="/llm/autograd-graph">自动微分与计算图</a>，金融栏的<a href="/quant/aad-adjoint">伴随算法微分 AAD</a> 给过定价里的用法。缺口在实现层：同一链式法则怎么落到程序上——重载、源码变换、录带回放各选什么，带子内存怎么还，稀疏 Jacobian 怎么接上一课的图。后课默认梯度可以按合同供给。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「自动微分零成本」是广告，实际要付三类钱：每步常数倍的额外算术（正向与反向各算各的）、反向的中间值存储、以及不可微处的约定。三类钱不挑明，实现就在两处翻车：深计算图把带子堆到内存爆炸；或把前向代码机械复用当 VJP，数值上重新付一遍指数甚至上溢。缺口是把这些代价变成可选、可算、可归因的工程参数。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>正向模式不录带：对偶数 \\((v,\\dot v)\\) 随原程序走，运算符重载在数类型上长出一套伴随算术，适合 \\(n\\) 小 \\(m\\) 大、或导数要随点更新的场景。反向模式分两趟：先录带——Wengert 列表记下每个原语的输入与局部导数——再逆序扫一遍做伴随累计；带子内存 \\(O(\\#op)\\)，还债靠检查点：前向每隔一段存状态，反向时局部重算，二项检查点把重算次数压到对数量级（Griewank 与 Walther 的账）。二阶信息用 forward-over-reverse 组合：先带切向量正向扫，再反向，一次得 Hessian-vector 积。</p>',7)),(A(),n(l,null,{default:t(()=>[B(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRG%5B%22%E5%8E%9F%E7%A8%8B%E5%BA%8F%EF%BC%9A%E5%8F%AA%E7%AE%97%E5%80%BC%22%5D%20--%3E%20FWD%5B%22%E6%AD%A3%E5%90%91%EF%BC%9A%E9%87%8D%E8%BD%BD%E5%AF%B9%E5%81%B6%E6%95%B0%EF%BC%8C%E6%90%BA%E5%B8%A6%E5%88%87%E5%90%91%E9%87%8F%22%5D%0A%20%20PRG%20--%3E%20TAPE%5B%22%E5%8F%8D%E5%90%91%EF%BC%9A%E5%BD%95%E5%B8%A6%20Wengert%20%E5%88%97%E8%A1%A8%22%5D%0A%20%20TAPE%20--%3E%20MEM%5B%22%E5%B8%A6%E5%AD%90%E5%86%85%E5%AD%98%20O(%E6%93%8D%E4%BD%9C%E6%95%B0)%22%5D%0A%20%20MEM%20--%3E%20CKPT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%EF%BC%9A%E9%87%8D%E7%AE%97%E6%8D%A2%E5%86%85%E5%AD%98%22%5D%0A%20%20TAPE%20--%3E%20ADJ%5B%22%E9%80%86%E5%BA%8F%E6%89%AB%E6%8F%8F%EF%BC%9A%E4%BC%B4%E9%9A%8F%E7%B4%AF%E8%AE%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("实现质量的分界线在 VJP 的写法：伴随公式要按输出的"),e("strong",null,"稳定形式"),E("重写，不能机械复用前向代码。softmax 是标准反例：前向算过 \\(\\exp\\)，反向若照抄要重指一道指数并可能上溢；改用输出写 \\(\\bar x_i=p_i\\bigl(\\bar y_i-\\sum_j p_j\\bar y_j\\bigr)\\)，省一半指数又天然有界——上一课「把舍入集中到无害位置」的思维在这里变现。分支与折点是第二处分界："),e("code",null,"if"),E(" 走了哪支、"),e("code",null,"max"),E(" 在何处折弯，必须记进带子并固定约定（次梯度取哪一侧），否则同一段代码两次运行给出不同导数，优化器的诊断全部失真。")],-1)),a[5]||(a[5]=e("p",null,"稀疏 Jacobian 是第三处：结构稀疏时不必逐列扫描——把「两列从不出现在同一行」画成二部图，图着色分组，一个种子方向覆盖一整组互不相交的列，正向扫 \\(\\chi\\) 次（色数）就填满整个 Jacobian；反向同理按行分组。上一课的图视角在这里直接接上：稀疏性是计算图的性质，导数矩阵继承它。",-1)),(A(),n(l,null,{default:t(()=>[B(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20J%5B%22%E7%A8%80%E7%96%8F%20Jacobian%20%E7%9A%84%E5%88%97%22%5D%20--%3E%20G%5B%22%E7%94%BB%E4%BA%8C%E9%83%A8%E5%9B%BE%3A%20%E8%A1%8C%C3%97%E5%88%97%2C%20%E6%9C%89%E9%9D%9E%E9%9B%B6%E5%88%99%E8%BF%9E%E8%BE%B9%22%5D%0A%20%20G%20--%3E%20COL%7B%22%E4%B8%A4%E5%88%97%E5%85%B1%E4%BA%AB%E6%9F%90%E4%B8%80%E8%A1%8C%E9%9D%9E%E9%9B%B6%3F%22%7D%0A%20%20COL%20--%20%22%E4%B8%8D%E5%85%B1%E4%BA%AB%22%20--%3E%20GRP%5B%22%E5%BD%92%E5%85%A5%E5%90%8C%E8%89%B2%E7%BB%84%3A%20%E5%8F%AF%E7%94%A8%E5%90%8C%E4%B8%80%E6%89%B0%E5%8A%A8%E6%96%B9%E5%90%91%22%5D%0A%20%20COL%20--%20%22%E5%85%B1%E4%BA%AB%22%20--%3E%20SEP%5B%22%E5%BF%85%E9%A1%BB%E5%BC%82%E8%89%B2%3A%20%E5%90%A6%E5%88%99%E5%88%97%E9%97%B4%E4%B8%B2%E6%89%B0%22%5D%0A%20%20GRP%20--%3E%20SEED%5B%22%E6%AF%8F%E7%BB%84%E9%85%8D%E4%B8%80%E4%B8%AA%E7%A7%8D%E5%AD%90%E5%90%91%E9%87%8F%22%5D%0A%20%20SEED%20--%3E%20SCAN%5B%22%E6%AD%A3%E5%90%91%E6%89%AB%E6%8F%8F%20%3D%20%E8%89%B2%E6%95%B0%E6%AC%A1%2C%20%E5%A1%AB%E6%BB%A1%E6%95%B4%E4%B8%AA%E7%9F%A9%E9%98%B5%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>这张图回答的问题是：稀疏 Jacobian 为什么不必逐列扫描——着色把「互不碰行」的列并成一组，一次种子扰动同时测一组列，扫描次数从列数降到色数。</p><p><span class="marginnote">反向模式一次反向的代价约为前向的 2 到 4 倍算术加带子管理——这是 Griewank 与 Walther 给的经验界；AAD 在金融库里能活着，靠的就是这个常数倍，而不是「导数免费」。</span></p><p><span class="marginnote">「带子」（Wengert 列表）就是反向模式记的流水账：每个原语操作一行，记输入和局部导数。反向扫描时从最后一行倒着读、逐行乘上伴随——它把「整条链式法则」拆成了一串查表乘法。</span></p><p><span class="marginnote">数字实例：\\(n=10^4\\) 个输入、\\(m=1\\) 个输出的函数，反向一次得全梯度（代价约 2–4 倍前向）；正向模式要扫 1 万次才能凑齐同样信息。反过来，\\(m\\gg n\\) 时结论倒置——选模式先数 \\(n\\) 和 \\(m\\) 谁大。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重算两种模式的复杂度（引用课已给），不进异构与分布式的梯度同步，不写任意精度微分。带子、检查点与着色都有实现成本，问题足够小或导数手写更短时，AD 不是默认答案。后课默认：梯度供给是优化库里的一条合同轴——解析、AD 或差分任选其一，下一课把它当输入。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正向重载零录带，反向录带换全局性；选择由 \\(n\\) 与 \\(m\\) 谁大决定。</li><li>带子内存用检查点还：二项检查点把重算压到对数量级。</li><li>VJP 按输出的稳定形式重写；softmax 反例是实现质量的分界线。</li><li>分支与折点记进带子并固定约定，否则导数不可复现。</li><li>稀疏 Jacobian 用图着色分组，导数矩阵继承计算图的稀疏性。</li><li>出处：Wengert, Comm. ACM, 1964；Griewank and Walther, 2008；Baydin et al., JMLR, 2018。</li></ul>',8))])}const _=o(p,[["render",m]]);export{F as __pageData,_ as default};
